cat > /app/output/styles.css << 'EOF'
:root {
  --bg: #f7f8fb;
  --surface: #ffffff;
  --text: #141628;
  --muted: #5f6474;
  --primary: #0a0a23;
  --accent: #feac32;
  --link: #002ead;
  --border: #e8eaf0;
  --radius: 14px;
  --shadow: 0 8px 24px rgba(10, 10, 35, 0.08);
}

* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.5;
}
a { color: var(--link); text-decoration: none; }
a:hover { text-decoration: underline; }

.container { width: min(1120px, 92vw); margin: 0 auto; }

.site-header { background: var(--primary); color: #fff; position: sticky; top: 0; z-index: 20; }
.header-inner {
  display: flex; align-items: center; gap: 1rem;
  padding: 0.9rem 0;
}
.logo { color: #fff; font-weight: 800; font-size: 1.2rem; letter-spacing: .2px; }
.logo-mark { color: var(--accent); }
.search-wrap { flex: 1; }
.search-wrap input {
  width: 100%; border: 1px solid rgba(255,255,255,.18);
  background: rgba(255,255,255,.08); color: #fff;
  border-radius: 10px; padding: .7rem .9rem;
}
.search-wrap input::placeholder { color: rgba(255,255,255,.7); }
.nav-links { display: flex; gap: 1.2rem; }
.nav-links a { color: #fff; font-weight: 600; }
.menu-btn {
  display: none; border: 1px solid rgba(255,255,255,.3); background: transparent;
  color: #fff; border-radius: 10px; padding: .5rem .65rem; cursor: pointer;
}
.mobile-nav { display: none; padding: .6rem 0 1rem; }
.mobile-nav.open { display: grid; gap: .5rem; }
.mobile-nav a {
  color: #fff; padding: .55rem .7rem; border-radius: 8px;
  background: rgba(255,255,255,.08);
}

.banner {
  background: #11153b; color: #fff; border-top: 1px solid rgba(255,255,255,.08);
  border-bottom: 1px solid rgba(255,255,255,.08);
}
.banner a {
  color: #fff; display: inline-block; padding: .55rem 0; font-weight: 600;
}

main { padding: 2rem 0 3.5rem; }
.section-title { font-size: 1.6rem; margin: 0 0 .35rem; }
.section-sub { color: var(--muted); margin: 0 0 1.2rem; }

.featured-card {
  position: relative; background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow);
  margin-bottom: 1.5rem;
}
.thumb { width: 100%; height: 230px; object-fit: cover; display: block; background: #e8ebf6; }
.featured-content { padding: 1rem 1.1rem 1.2rem; }

.tag {
  display: inline-block; font-size: .76rem; font-weight: 700; text-transform: uppercase;
  padding: .25rem .55rem; border-radius: 999px; margin-bottom: .7rem;
  letter-spacing: .3px;
}
.tag-ai { background: #e7ecff; color: #2442a5; }
.tag-scrape { background: #e8faf3; color: #0e7a50; }
.tag-db { background: #fff3df; color: #8d5a00; }
.tag-es { background: #f6ecff; color: #6b2ca1; }
.tag-de { background: #ffeaf0; color: #a4214b; }

h1, h2, h3 { line-height: 1.25; }
.card-title { margin: 0 0 .8rem; font-size: 1.16rem; }
.author-row {
  display: flex; align-items: center; gap: .6rem; color: var(--muted); font-size: .92rem;
}
.avatar {
  width: 32px; height: 32px; border-radius: 50%;
  object-fit: cover; border: 2px solid #fff; box-shadow: 0 2px 8px rgba(0,0,0,.12);
}

.grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1rem;
}
.card {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); overflow: hidden; box-shadow: 0 3px 12px rgba(10,10,35,.05);
}
.card .thumb { height: 165px; }
.card-content { padding: .9rem .95rem 1rem; }
.load-more-wrap { text-align: center; margin-top: 1.2rem; }
.btn {
  border: none; border-radius: 999px; padding: .68rem 1.1rem;
  font-weight: 700; cursor: pointer; transition: .2s ease;
}
.btn-primary { background: var(--accent); color: #2a1900; }
.btn-primary:hover { transform: translateY(-1px); filter: brightness(.97); }

.panel {
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 1.2rem;
}
.path-grid {
  display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: .8rem;
}
.path-item {
  display: flex; gap: .7rem; align-items: flex-start; padding: .75rem .8rem;
  border: 1px solid var(--border); border-radius: 10px; background: #fbfcff;
}
.icon {
  width: 30px; height: 30px; border-radius: 8px; background: #e9eeff;
  display: grid; place-items: center; color: #2046a7; font-weight: 800;
}

.donate-hero { display: grid; grid-template-columns: 1.15fr .85fr; gap: 1rem; }
.amount-tabs { display: grid; grid-template-columns: repeat(4,1fr); gap: .45rem; margin: .95rem 0; }
.amount-tab {
  border: 1px solid var(--border); background: #fff; border-radius: 10px;
  padding: .52rem; font-weight: 700; cursor: pointer;
}
.amount-tab.active { border-color: #e19a24; background: #fff5e6; color: #7a4d00; }
.small-note { color: var(--muted); font-size: .9rem; }
.list { margin: .5rem 0 0 0; padding-left: 1.1rem; }
.list li { margin: .45rem 0; }

.faq-item { border-top: 1px solid var(--border); }
.faq-btn {
  width: 100%; text-align: left; border: none; background: transparent;
  padding: .95rem 0; font-weight: 650; color: var(--text); cursor: pointer;
}
.faq-content {
  max-height: 0; overflow: hidden; color: var(--muted);
  transition: max-height .3s ease;
}
.faq-content p { margin: 0 0 .9rem; }
.faq-item.open .faq-content { max-height: 180px; }

.tag-head { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; }
.tag-count { color: var(--muted); font-weight: 600; }
.pop-tags {
  display: flex; gap: .55rem; overflow-x: auto; padding-bottom: .25rem; margin: .7rem 0 1.2rem;
}
.pop-tags a {
  white-space: nowrap; border: 1px solid var(--border); border-radius: 999px;
  padding: .45rem .75rem; background: #fff; color: #263252; font-size: .9rem;
}

footer {
  border-top: 1px solid var(--border); background: #fff; color: var(--muted);
}
footer .container { padding: 1rem 0; font-size: .92rem; }

@media (max-width: 980px) {
  .grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
  .donate-hero { grid-template-columns: 1fr; }
}
@media (max-width: 760px) {
  .search-wrap { display: none; }
  .nav-links { display: none; }
  .menu-btn { display: inline-flex; }
  .grid, .path-grid { grid-template-columns: 1fr; }
}
EOF

cat > /app/output/script.js << 'EOF'
(function () {
  const menuBtn = document.querySelector('[data-menu-btn]');
  const mobileNav = document.querySelector('[data-mobile-nav]');
  if (menuBtn && mobileNav) {
    menuBtn.addEventListener('click', function () {
      const open = mobileNav.classList.toggle('open');
      menuBtn.setAttribute('aria-expanded', String(open));
    });
  }

  const articleGrid = document.querySelector('[data-article-grid]');
  const loadMoreBtn = document.querySelector('[data-load-more]');
  const moreArticles = [
    { tag: '#AI', cls: 'tag-ai', title: 'The AI Governance Handbook: How to Build Responsible AI Systems That Actually Ship', author: 'Amina Okafor', time: '2 days ago' },
    { tag: '#web scraping', cls: 'tag-scrape', title: 'How to Turn Websites into LLM-Ready Data Using Firecrawl', author: 'Kelechi Udo', time: '3 days ago' },
    { tag: '#web scraping', cls: 'tag-scrape', title: 'How to Use Python to Build Your Own Web Scraper', author: 'Marta Ruiz', time: '4 days ago' },
    { tag: '#AI', cls: 'tag-ai', title: 'GPT-5.4 vs GLM-5: Is Open Source Finally Matching Proprietary AI?', author: 'Devon Harper', time: '5 days ago' }
  ];

  function cardTemplate(item) {
    return '<article class="card">' +
      '<img class="thumb" src="https://picsum.photos/seed/' + encodeURIComponent(item.title.slice(0, 18)) + '/640/360" alt="Article thumbnail">' +
      '<div class="card-content">' +
      '<a href="' + (item.tag.toLowerCase().includes('web scraping') ? 'tag-web-scraping.html' : (item.tag === '#AI' ? 'tag-ai.html' : '#')) + '"><span class="tag ' + item.cls + '">' + item.tag + '</span></a>' +
      '<h3 class="card-title">' + item.title + '</h3>' +
      '<div class="author-row"><img class="avatar" src="https://i.pravatar.cc/64?u=' + encodeURIComponent(item.author) + '" alt="Author avatar"><span>' + item.author + ' · ' + item.time + '</span></div>' +
      '</div></article>';
  }

  if (articleGrid && loadMoreBtn) {
    loadMoreBtn.addEventListener('click', function () {
      articleGrid.insertAdjacentHTML('beforeend', moreArticles.map(cardTemplate).join(''));
      loadMoreBtn.disabled = true;
      loadMoreBtn.textContent = 'All Articles Loaded';
    });
  }

  const donationTabs = document.querySelectorAll('[data-amount]');
  const donationText = document.querySelector('[data-donation-text]');
  if (donationTabs.length && donationText) {
    donationTabs.forEach(function (tab) {
      tab.addEventListener('click', function () {
        donationTabs.forEach(function (t) { t.classList.remove('active'); });
        tab.classList.add('active');
        const amount = tab.getAttribute('data-amount');
        donationText.textContent = 'Your $' + amount + ' donation will provide 1,000 hours of learning to people around the world each month.';
        const sub = document.querySelector('[data-donation-sub]');
        if (sub) sub.textContent = 'Donating $' + amount + ' / month: edit amount · Secure donation';
      });
    });
  }

  const faqBtns = document.querySelectorAll('[data-faq-btn]');
  faqBtns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      btn.parentElement.classList.toggle('open');
    });
  });
})();
EOF

